rex(g,r'    private Viewport viewport\(\)\{.*?return new Viewport\(tile,ox,oy,contentW,contentH,scale,cameraX,cameraY\);\}',r'''    private Viewport viewport(){double cw=Math.max(1,canvas.getWidth()),ch=Math.max(1,canvas.getHeight()),lw=Math.max(1,project.getLogicalWidth()),lh=Math.max(1,project.getLogicalHeight()),scale;if(project.getScaleMode()==ScaleMode.STRETCH){double sx=cw/lw,sy=ch/lh;scale=Math.min(sx,sy);}else{double raw=Math.min(cw/lw,ch/lh);scale=project.isIntegerScale()&&raw>=1?Math.max(1,Math.floor(raw)):Math.max(.05,raw);}double contentW=lw*scale,contentH=lh*scale,ox=Math.floor((cw-contentW)/2),oy=Math.floor((ch-contentH)/2);if(!cameraInitialized)updateCamera(0);CameraState camera=cameraState();double tile=Math.max(.1,project.getTileSize()*scale*camera.zoom),viewW=lw/(project.getTileSize()*camera.zoom),viewH=lh/(project.getTileSize()*camera.zoom),cameraX=camera.centerX-viewW/2+camera.offsetX,cameraY=camera.centerY-viewH/2+camera.offsetY;double minX=Double.isFinite(cameraMinX)?cameraMinX:0,minY=Double.isFinite(cameraMinY)?cameraMinY:0,maxX=Double.isFinite(cameraMaxX)?cameraMaxX:level.width,maxY=Double.isFinite(cameraMaxY)?cameraMaxY:level.height;if(maxX<=minX){minX=0;maxX=level.width;}if(maxY<=minY){minY=0;maxY=level.height;}if(maxX-minX<=viewW)cameraX=minX+(maxX-minX-viewW)/2;else cameraX=Math.max(minX,Math.min(maxX-viewW,cameraX));if(maxY-minY<=viewH)cameraY=minY+(maxY-minY-viewH)/2;else cameraY=Math.max(minY,Math.min(maxY-viewH,cameraY));if(camera.pixelSnap){double step=1.0/Math.max(1,project.getTileSize());cameraX=Math.rint(cameraX/step)*step;cameraY=Math.rint(cameraY/step)*step;}return new Viewport(tile,ox,oy,contentW,contentH,scale,cameraX,cameraY);}''')
