# ---------------------------------------------------------------------------
# 2GameScript: bounded while loops. This removes the most restrictive loop
# limitation without allowing an unbounded event to freeze the runtime.
# ---------------------------------------------------------------------------
s='src/main/java/com/buttclapdev/twogamerl/script/ScriptProgram.java'
rep(s,'    private record RepeatInstruction(int count,List<Instruction>body) implements Instruction {}','    private record RepeatInstruction(int count,List<Instruction>body) implements Instruction {}\n    private record WhileInstruction(Condition condition,List<Instruction>body,int limit) implements Instruction {}\n    private record WhileStepInstruction(Condition condition,List<Instruction>body,int remaining) implements Instruction {}')
rep(s,'private static void executeQueue(ArrayDeque<Instruction>q,Context c){int guard=0;while(!q.isEmpty()&&guard++<100000){Instruction i=q.removeFirst();if(i instanceof WaitInstruction w){ArrayDeque<Instruction>cont=new ArrayDeque<>(q);c.schedule(w.seconds(),()->executeQueue(cont,c));return;}if(i instanceof IfInstruction f){pushFront(q,f.condition().test(c)?f.yes():f.no());continue;}if(i instanceof RepeatInstruction r){for(int n=0;n<r.count();n++)pushFront(q,r.body());continue;}if(i==StopInstruction.INSTANCE)return;try{i.run(c);}catch(RuntimeException ex){c.log("Script: "+(ex.getMessage()==null?ex.getClass().getSimpleName():ex.getMessage()));}}if(guard>=100000)c.log("Script: se alcanzó el límite de instrucciones de un evento.");}','private static void executeQueue(ArrayDeque<Instruction>q,Context c){int guard=0;while(!q.isEmpty()&&guard++<100000){Instruction i=q.removeFirst();if(i instanceof WaitInstruction w){ArrayDeque<Instruction>cont=new ArrayDeque<>(q);c.schedule(w.seconds(),()->executeQueue(cont,c));return;}if(i instanceof IfInstruction f){pushFront(q,f.condition().test(c)?f.yes():f.no());continue;}if(i instanceof RepeatInstruction r){for(int n=0;n<r.count();n++)pushFront(q,r.body());continue;}if(i instanceof WhileInstruction w){q.addFirst(new WhileStepInstruction(w.condition(),w.body(),w.limit()));continue;}if(i instanceof WhileStepInstruction w){if(!w.condition().test(c))continue;if(w.remaining()<=0){c.log("Script: while alcanzó el límite de 10000 iteraciones.");continue;}q.addFirst(new WhileStepInstruction(w.condition(),w.body(),w.remaining()-1));pushFront(q,w.body());continue;}if(i==StopInstruction.INSTANCE)return;try{i.run(c);}catch(RuntimeException ex){c.log("Script: "+(ex.getMessage()==null?ex.getClass().getSimpleName():ex.getMessage()));}}if(guard>=100000)c.log("Script: se alcanzó el límite de instrucciones de un evento.");}')
